import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    hi = -1
    mx = a[0]
    for i in range(1, n):
        if a[i] < mx:
            hi = i
        else:
            mx = a[i]
    lo = -1
    mn = a[-1]
    for i in range(n - 2, -1, -1):
        if a[i] > mn:
            lo = i
        else:
            mn = a[i]
    print(0 if hi < 0 else hi - lo + 1)

main()

