best = 0
if a != sorted(a):
    best = n
    for l in range(n):
        for r in range(l, n):
            b = a[:l] + sorted(a[l:r + 1]) + a[r + 1:]
            if b == sorted(a) and r - l + 1 < best:
                best = r - l + 1
